cd /home/runner/work/PlayGround/PlayGround && node - <<'EOF'
const { execSync } = require('child_process');
const fs = require('fs');
const css = execSync(`curl -s --max-time 30 -H "User-Agent: Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0 Safari/537.36" "https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400;0,500;0,600;1,400;1,500&family=Manrope:wght@400;500;600;700;800&display=swap"`).toString();
const blocks = css.split('/* ').slice(1);
let out = '';
for (const b of blocks) {
  const subset = b.split(' */')[0];
  if (!['latin','latin-ext'].includes(subset)) continue;
  const fam = (b.match(/font-family: '([^']+)'/)||[])[1];
  const style = (b.match(/font-style: ([a-z]+)/)||[])[1];
  const weight = (b.match(/font-weight: ([\d]+)/)||[])[1];
  const url = (b.match(/url\((https:[^)]+)\)/)||[])[1];
  if (!fam || !url) continue;
  const file = `${fam.toLowerCase()}-${weight}-${style}-${subset}.woff2`;
  execSync(`curl -s --max-time 30 -o assets/fonts/${file} "${url}"`);
  out += `@font-face{font-family:'${fam}';font-style:${style};font-weight:${weight};font-display:swap;src:url('assets/fonts/${file}') format('woff2');}\n`;
}
fs.writeFileSync('assets/fonts/fonts.css', out);
console.log(out);
console.log(fs.readdirSync('assets/fonts'));
EOF

