cd /home/runner/work/PlayGround/PlayGround && node - <<'EOF'
const fs=require('fs'), vm=require('vm');
const ctx={window:{}}; vm.createContext(ctx);
for (const f of ['data/wardrobe.js','data/events-a.js','data/events-b.js','data/events-c.js','data/events-d.js','data/events-proc.js']) vm.runInContext(fs.readFileSync(f,'utf8'),ctx);
const w=ctx.window;
const all=[...w.STORY_EVENTS,...w.PROC_EVENTS];
const ids=new Set(all.map(e=>e.id));
console.log('socks',w.WARDROBE.socks.length,'shoes',w.WARDROBE.shoes.length,'events',all.length,'proc',w.PROC_EVENTS.length);
const dup=all.map(e=>e.id).filter((id,i,a)=>a.indexOf(id)!==i); console.log('dup events',dup);
for(const e of all){
  if(!e.choices||e.choices.length!==4) console.log('BAD choices',e.id,e.choices&&e.choices.length);
  for(const c of e.choices){
    if(!c.next||!ids.has(c.next)) console.log('BAD next',e.id,c.label,c.next);
    if(c.trigger&&!ids.has(c.trigger)) console.log('BAD trigger',e.id,c.trigger);
  }
}
const sids=w.WARDROBE.socks.map(s=>s.id), shids=w.WARDROBE.shoes.map(s=>s.id);
console.log('dup sock',sids.filter((x,i,a)=>a.indexOf(x)!==i),'dup shoe',shids.filter((x,i,a)=>a.indexOf(x)!==i));
// reachability from gece-baslangic through next + trigger
const map=Object.fromEntries(all.map(e=>[e.id,e]));
const seen=new Set(); const stack=['gece-baslangic'];
while(stack.length){const id=stack.pop(); if(seen.has(id)||!map[id])continue; seen.add(id); for(const c of map[id].choices){stack.push(c.next); if(c.trigger)stack.push(c.trigger);} }
console.log('reachable',seen.size,'of',all.length,'unreachable',all.filter(e=>!seen.has(e.id)).map(e=>e.id));
console.log('heels',w.WARDROBE.shoes.filter(s=>s.heel>0).length);
EOF

