/* ============================================================
   GECE DEVRİYESİ — temel görsel sistem
   ============================================================ */
:root {
  --bg: #060810;
  --bg-deep: #03040a;
  --panel: #0b101d;
  --panel-2: #101728;
  --panel-3: #151d31;
  --ink: #f4f0e8;
  --ink-soft: #ddd8cf;
  --muted: #9aa4b9;
  --faint: #69748d;
  --pink: #ff5f8f;
  --pink-soft: #ff9ab6;
  --cyan: #6ee7f2;
  --cyan-soft: #a7f3f8;
  --gold: #ffd27d;
  --green: #7ee0b8;
  --danger: #ff7474;
  --line: rgba(255, 255, 255, 0.09);
  --line-soft: rgba(255, 255, 255, 0.055);
  --glass: rgba(9, 13, 24, 0.76);
  --shadow: 0 26px 80px rgba(0, 0, 0, 0.55);
  --radius: 18px;
  --sans: "Manrope", "Trebuchet MS", system-ui, sans-serif;
  --serif: "Lora", Georgia, "Times New Roman", serif;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
}

html {
  background: var(--bg-deep);
  -webkit-text-size-adjust: 100%;
}

body {
  min-height: 100dvh;
  overflow: hidden;
  color: var(--ink);
  background:
    radial-gradient(120% 90% at 50% 10%, #101424 0%, #070a12 45%, #03040a 100%);
  font-family: var(--sans);
  font-size: 15px;
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button {
  margin: 0;
  padding: 0;
  border: 0;
  color: inherit;
  background: none;
  font: inherit;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible,
[tabindex]:focus-visible {
  outline: 2px solid var(--pink-soft);
  outline-offset: 2px;
}

h1,
h2,
h3,
p {
  margin: 0;
}

svg {
  display: block;
}

.hidden {
  display: none !important;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ---------------- Ambient backdrop ---------------- */
.ambient {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  background:
    linear-gradient(115deg, rgba(255, 95, 143, 0.03), transparent 40%),
    radial-gradient(90% 70% at 80% 10%, rgba(110, 231, 242, 0.07), transparent 60%);
}

.ambient__glow {
  position: absolute;
  width: 48vw;
  height: 48vw;
  min-width: 340px;
  min-height: 340px;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.5;
}

.ambient__glow--pink {
  top: -20%;
  left: -12%;
  background: rgba(255, 95, 143, 0.18);
}

.ambient__glow--cyan {
  right: -14%;
  bottom: -22%;
  background: rgba(110, 231, 242, 0.12);
}

.ambient__grain {
  position: absolute;
  inset: -50%;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.85'/%3E%3C/svg%3E");
  background-size: 180px 180px;
  animation: grainShift 1.2s steps(2) infinite;
}

.ambient__line {
  position: absolute;
  width: 1px;
  height: 130vh;
  background: linear-gradient(to bottom, transparent, rgba(255, 255, 255, 0.09), transparent);
  transform: rotate(24deg);
}

.ambient__line--one {
  top: -20vh;
  left: 16%;
}

.ambient__line--two {
  top: -10vh;
  right: 24%;
  opacity: 0.6;
}

@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  25% { transform: translate3d(-2%, 1%, 0); }
  50% { transform: translate3d(1%, -2%, 0); }
  75% { transform: translate3d(2%, 2%, 0); }
  100% { transform: translate3d(-1%, -1%, 0); }
}

/* ---------------- Stage / device ---------------- */
.stage {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: clamp(36px, 7vw, 120px);
  min-height: 100dvh;
  padding: 24px;
}

.device {
  position: relative;
  width: min(440px, calc(100vw - 32px));
  height: min(900px, calc(100dvh - 32px));
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 34px;
  background: var(--bg);
  box-shadow:
    0 0 0 1px rgba(0, 0, 0, 0.5),
    0 40px 100px rgba(0, 0, 0, 0.65),
    inset 0 0 0 1px rgba(255, 255, 255, 0.03);
}

.device::before {
  content: "";
  position: absolute;
  top: 0;
  left: 22%;
  right: 22%;
  height: 18px;
  border-radius: 0 0 14px 14px;
  background: rgba(255, 255, 255, 0.035);
  z-index: 30;
  pointer-events: none;
}

.app {
  position: relative;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background:
    radial-gradient(90% 70% at 50% 0%, rgba(35, 48, 79, 0.35), transparent 55%),
    var(--bg);
  isolation: isolate;
}

/* ---------------- Poster (desktop) ---------------- */
.poster {
  width: min(400px, 30vw);
  color: var(--ink);
}

.poster__top {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 34px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  line-height: 1.5;
}

.poster__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--pink);
  box-shadow: 0 0 16px rgba(255, 95, 143, 0.9);
  animation: dotPulse 2.4s ease-in-out infinite;
}

@keyframes dotPulse {
  0%, 100% { opacity: 0.45; transform: scale(0.85); }
  50% { opacity: 1; transform: scale(1.15); }
}

.poster h1 {
  font-family: var(--serif);
  font-size: clamp(58px, 5.4vw, 84px);
  font-weight: 400;
  line-height: 0.88;
  letter-spacing: -0.035em;
}

.poster h1 em {
  display: inline-block;
  padding-right: 0.05em;
  color: var(--pink-soft);
  font-style: italic;
  font-weight: 500;
  background: linear-gradient(120deg, #ffd5e0, var(--pink) 55%, #ffb36b);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.poster__lede {
  max-width: 330px;
  margin-top: 26px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 17px;
  line-height: 1.7;
}

.poster__rule {
  width: 100%;
  height: 1px;
  margin: 28px 0 22px;
  background: linear-gradient(to right, rgba(255, 255, 255, 0.18), transparent);
}

.poster__facts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px 28px;
}

.poster__facts div {
  display: flex;
  align-items: baseline;
  gap: 8px;
}

.poster__facts strong {
  font-family: var(--serif);
  font-size: 26px;
  font-weight: 400;
  color: var(--ink);
}

.poster__facts span {
  color: var(--faint);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.poster__foot {
  margin-top: 34px;
  color: rgba(255, 255, 255, 0.32);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.32em;
  line-height: 1.8;
}

.poster__stamp {
  display: inline-block;
  margin-top: 20px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 95, 143, 0.35);
  border-radius: 999px;
  color: var(--pink-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

/* ---------------- Common bits ---------------- */
.eyebrow {
  display: block;
  color: var(--pink-soft);
  font-size: 8.5px;
  font-weight: 800;
  letter-spacing: 0.22em;
  line-height: 1.4;
  text-transform: uppercase;
}

.eyebrow--light {
  color: rgba(255, 255, 255, 0.7);
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.4);
}

.brand-mini {
  display: flex;
  align-items: center;
  gap: 8px;
  color: rgba(255, 255, 255, 0.79);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.brand-mini__dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--pink);
  box-shadow: 0 0 10px rgba(255, 95, 143, 0.8);
}

.brand-mini__slash {
  color: rgba(255, 255, 255, 0.25);
}

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  flex: 0 0 auto;
  border: 1px solid var(--line);
  border-radius: 50%;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.035);
  transition: transform 140ms ease, background 140ms ease, border-color 140ms ease;
}

.icon-btn svg {
  width: 19px;
  height: 19px;
}

.icon-btn:active {
  transform: scale(0.92);
  background: rgba(255, 255, 255, 0.09);
}

.icon-btn--glass {
  color: #fff;
  border-color: rgba(255, 255, 255, 0.2);
  background: rgba(4, 6, 12, 0.28);
  backdrop-filter: blur(10px);
}

.icon-btn.is-muted .sound-wave {
  opacity: 0;
}

.icon-btn.is-muted::after {
  content: "";
  position: absolute;
  width: 20px;
  height: 1.5px;
  margin-top: 1px;
  background: var(--danger);
  transform: rotate(-45deg);
  border-radius: 2px;
}

.btn {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  min-height: 56px;
  padding: 0 18px;
  overflow: hidden;
  border-radius: 15px;
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.02em;
  transition: transform 130ms ease, filter 130ms ease, box-shadow 130ms ease;
}

.btn:: before {
  content: "";
}

.btn:active {
  transform: scale(0.984);
}

.btn--primary {
  color: #120710;
  background:
    linear-gradient(115deg, #ffd3df 0%, var(--pink) 42%, #ff8a5f 100%);
  box-shadow:
    0 10px 30px rgba(255, 95, 143, 0.25),
    inset 0 1px 0 rgba(255, 255, 255, 0.5);
}

.btn--primary::after {
  content: "";
  position: absolute;
  top: 0;
  left: -40%;
  width: 35%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.38), transparent);
  transform: skewX(-18deg);
  animation: btnShine 5.5s ease-in-out infinite;
}

@keyframes btnShine {
  0%, 60% { left: -45%; }
  100% { left: 125%; }
}

.btn__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: rgba(12, 5, 10, 0.13);
  font-size: 16px;
  line-height: 1;
}

.btn--ghost {
  justify-content: center;
  color: var(--ink);
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.035);
}

.btn--continue {
  justify-content: space-between;
  color: var(--ink);
  border: 1px solid rgba(110, 231, 242, 0.28);
  background: linear-gradient(100deg, rgba(110, 231, 242, 0.1), rgba(255, 255, 255, 0.03));
}

.btn__continue-main {
  display: flex;
  align-items: center;
  gap: 9px;
}

.btn__continue-main::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 12px rgba(110, 231, 242, 0.8);
}

.btn__continue-meta {
  color: var(--cyan-soft);
  font-size: 9px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.text-btn {
  padding: 8px 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-decoration: underline;
  text-decoration-color: rgba(255, 255, 255, 0.17);
  text-underline-offset: 4px;
}

.text-btn--muted {
  color: var(--faint);
}

.mini-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 24px;
  padding: 0 9px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.03);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.mini-btn:active {
  background: rgba(255, 255, 255, 0.09);
}

.tiny-note {
  padding: 12px 2px 18px;
  color: var(--faint);
  font-size: 9.5px;
  line-height: 1.6;
  text-align: center;
}

/* ---------------- Screens ---------------- */
.screen {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  min-height: 0;
  background: var(--bg);
}

.screen.is-active {
  display: flex;
  animation: screenIn 420ms cubic-bezier(0.22, 0.8, 0.18, 1) both;
}

@keyframes screenIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------------- HOME ---------------- */
.screen--home {
  background: var(--bg);
}

.home-hero {
  position: relative;
  flex: 0 0 clamp(300px, 47%, 390px);
  min-height: 0;
  overflow: hidden;
  background: #0b1220;
}

.home-art {
  position: absolute;
  inset: 0;
}

.home-art svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.home-hero__scrim {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(to bottom, rgba(5, 7, 13, 0.32) 0%, transparent 32%, rgba(5, 7, 13, 0.34) 62%, #060810 100%),
    linear-gradient(to right, rgba(5, 7, 13, 0.35), transparent 55%);
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: calc(10px + var(--safe-top)) 16px 0;
}

.topbar--over {
  position: relative;
  z-index: 3;
}

.home-title {
  position: absolute;
  left: 22px;
  right: 22px;
  bottom: 26px;
  z-index: 2;
}

.home-title h1 {
  margin-top: 9px;
  font-family: var(--serif);
  font-size: clamp(52px, 14vw, 64px);
  font-weight: 400;
  line-height: 0.86;
  letter-spacing: -0.045em;
  text-shadow: 0 8px 40px rgba(0, 0, 0, 0.6);
}

.home-title h1 em {
  display: inline-block;
  padding-right: 0.04em;
  font-style: italic;
  font-weight: 500;
  background: linear-gradient(110deg, #ffe0e8 3%, var(--pink) 48%, #ffb56d 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
}

.home-title > p {
  margin-top: 9px;
  color: rgba(255, 255, 255, 0.78);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.06em;
}

.home-hero__meta {
  position: absolute;
  right: 18px;
  bottom: 29px;
  z-index: 2;
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding-left: 12px;
  border-left: 1px solid rgba(255, 255, 255, 0.22);
  color: rgba(255, 255, 255, 0.62);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-align: right;
}

.home-body {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 18px 22px calc(16px + var(--safe-bottom));
  background:
    radial-gradient(80% 70% at 20% 0%, rgba(255, 95, 143, 0.06), transparent 60%),
    linear-gradient(to bottom, #060810, #080b13 60%, #060810);
  scrollbar-width: none;
}

.home-body::-webkit-scrollbar {
  display: none;
}

.lede {
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 13.5px;
  line-height: 1.58;
}

.home-facts {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  margin: 15px 0 16px;
  border-top: 1px solid var(--line-soft);
  border-bottom: 1px solid var(--line-soft);
}

.home-facts div {
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 9px 0 8px;
  text-align: center;
  border-right: 1px solid var(--line-soft);
}

.home-facts div:last-child {
  border-right: 0;
}

.home-facts strong {
  font-family: var(--serif);
  font-size: 20px;
  font-weight: 500;
  color: var(--ink);
}

.home-facts span {
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.home-body .btn + .btn {
  margin-top: 8px;
}

.home-links {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 27px;
  margin-top: 5px;
}

.home-note {
  padding-top: 3px;
  color: var(--faint);
  font-size: 8.5px;
  line-height: 1.5;
  text-align: center;
}

/* ---------------- Responsive ---------------- */
@media (max-width: 1100px) {
  .poster {
    display: none;
  }
}

@media (max-width: 640px) {
  .stage {
    padding: 0;
    gap: 0;
  }

  .device {
    width: 100%;
    height: 100dvh;
    border: 0;
    border-radius: 0;
    box-shadow: none;
  }

  .device::before {
    display: none;
  }

  .home-title {
    left: 20px;
    right: 18px;
  }

  .home-title h1 {
    font-size: clamp(48px, 14.5vw, 60px);
  }

  .home-hero {
    flex-basis: clamp(280px, 46dvh, 390px);
  }

  .home-body {
    padding-left: 20px;
    padding-right: 20px;
  }
}

@media (max-height: 700px) and (max-width: 640px) {
  .home-hero {
    flex-basis: 250px;
  }

  .home-title h1 {
    font-size: 48px;
  }

  .home-title > p,
  .home-hero__meta {
    display: none;
  }

  .home-body {
    padding-top: 13px;
  }

  .lede {
    font-size: 12.5px;
    line-height: 1.5;
  }

  .home-facts {
    margin: 10px 0 12px;
  }

  .home-facts div {
    padding: 6px 0;
  }

  .btn {
    min-height: 50px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    scroll-behavior: auto !important;
    transition-duration: 0.001ms !important;
  }
}

/* ============================================================
   GECE DEVRİYESİ — gardırop, hikâye, rapor
   ============================================================ */

/* ---------------- WARDROBE ---------------- */
.screen--wardrobe {
  background:
    radial-gradient(80% 55% at 85% 0%, rgba(255, 95, 143, 0.08), transparent 60%),
    linear-gradient(to bottom, #0a0e19, #060810 55%);
}

.shiftbar,
.storybar {
  position: relative;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex: 0 0 auto;
  min-height: 52px;
  padding: calc(8px + var(--safe-top)) 14px 8px;
}

.shiftbar {
  border-bottom: 1px solid var(--line-soft);
}

.shiftbar__mid {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  line-height: 1.2;
}

.shiftbar__kicker {
  color: var(--pink-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

.shiftbar__time {
  color: var(--ink);
  font-family: var(--serif);
  font-size: 15px;
  letter-spacing: 0.02em;
}

.wardrobe-scroll {
  position: relative;
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 13px 14px 8px;
  scrollbar-width: none;
  overscroll-behavior: contain;
}

.wardrobe-scroll::-webkit-scrollbar,
.story-scroll::-webkit-scrollbar,
.sheet__scroll::-webkit-scrollbar,
.report-scroll::-webkit-scrollbar {
  display: none;
}

.outfit-card {
  position: relative;
  display: flex;
  align-items: stretch;
  gap: 14px;
  min-height: 148px;
  padding: 12px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 20px;
  background:
    radial-gradient(140% 120% at 0% 0%, rgba(255, 95, 143, 0.13), transparent 48%),
    radial-gradient(100% 100% at 100% 100%, rgba(110, 231, 242, 0.07), transparent 55%),
    linear-gradient(140deg, rgba(20, 27, 46, 0.9), rgba(9, 13, 23, 0.98));
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.26);
}

.outfit-card::after {
  content: "";
  position: absolute;
  right: -30px;
  top: -40px;
  width: 120px;
  height: 120px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 50%;
  pointer-events: none;
}

.outfit-preview {
  position: relative;
  flex: 0 0 106px;
  min-height: 124px;
  overflow: hidden;
  border-radius: 14px;
  background:
    radial-gradient(80% 60% at 50% 20%, rgba(255, 95, 143, 0.18), transparent 70%),
    #080c16;
}

.outfit-preview svg {
  width: 100%;
  height: 100%;
}

.outfit-meta {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 0;
  padding: 2px 0;
}

.outfit-meta h2 {
  margin-top: 6px;
  overflow: hidden;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 20px;
  font-weight: 500;
  letter-spacing: -0.015em;
  line-height: 1.12;
  text-overflow: ellipsis;
}

.outfit-meta > p {
  margin-top: 4px;
  overflow: hidden;
  color: var(--muted);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.risk-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 10px;
}

.risk-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px 6px;
  border: 1px solid var(--line-soft);
  border-radius: 6px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.025);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  white-space: nowrap;
}

.risk-chip i {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: currentColor;
}

.risk-chip--good {
  color: var(--green);
}

.risk-chip--mid {
  color: var(--gold);
}

.risk-chip--bad {
  color: var(--danger);
}

.outfit-meta .mini-btn {
  align-self: flex-start;
  margin-top: 8px;
}

/* condition */
.condition-card {
  margin-top: 10px;
  padding: 11px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 15px;
  background: rgba(255, 255, 255, 0.024);
}

.condition-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.condition-head span:first-child {
  color: var(--ink-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

.condition-head .condition-warn {
  color: var(--danger);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.condition-warn--ok {
  color: var(--green) !important;
}

.cond-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
}

.cond-stat {
  min-width: 0;
}

.cond-stat__top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 4px;
  margin-bottom: 3px;
}

.cond-stat__top span:first-child {
  color: var(--faint);
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cond-stat__top span:last-child {
  color: var(--ink-soft);
  font-size: 9px;
  font-weight: 700;
}

.cond-bar {
  height: 3px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
}

.cond-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--green);
  transition: width 220ms ease;
}

.cond-bar i.is-mid {
  background: var(--gold);
}

.cond-bar i.is-bad {
  background: var(--danger);
}

.condition-actions {
  display: flex;
  gap: 6px;
  margin-top: 9px;
}

.cond-btn {
  flex: 1;
  min-height: 28px;
  padding: 0 8px;
  border: 1px solid var(--line);
  border-radius: 8px;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.035);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cond-btn:active:not(:disabled) {
  background: rgba(255, 95, 143, 0.14);
}

.cond-btn:disabled {
  opacity: 0.38;
  cursor: not-allowed;
}

.condition-hint {
  margin-top: 7px;
  color: var(--faint);
  font-size: 8px;
  line-height: 1.45;
}

/* tabs and grid */
.tabrow {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4px;
  margin-top: 14px;
  padding: 3px;
  border: 1px solid var(--line-soft);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.02);
}

.tab {
  min-height: 34px;
  border-radius: 8px;
  color: var(--faint);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  transition: color 140ms ease, background 140ms ease;
}

.tab span {
  margin-left: 4px;
  color: inherit;
  opacity: 0.55;
  font-size: 8px;
}

.tab.is-active {
  color: var(--ink);
  background: linear-gradient(120deg, rgba(255, 95, 143, 0.18), rgba(255, 255, 255, 0.05));
  box-shadow: inset 0 0 0 1px rgba(255, 95, 143, 0.18);
}

.filters {
  display: flex;
  gap: 5px;
  margin: 9px -14px 9px;
  padding: 0 14px;
  overflow-x: auto;
  scrollbar-width: none;
}

.filters::-webkit-scrollbar {
  display: none;
}

.filter {
  flex: 0 0 auto;
  min-height: 25px;
  padding: 0 9px;
  border: 1px solid var(--line-soft);
  border-radius: 999px;
  color: var(--faint);
  background: rgba(255, 255, 255, 0.02);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.filter.is-active {
  color: var(--ink);
  border-color: rgba(255, 95, 143, 0.32);
  background: rgba(255, 95, 143, 0.12);
}

.item-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
}

.item-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  min-height: 92px;
  padding: 5px 5px 6px;
  overflow: hidden;
  border: 1px solid var(--line-soft);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.022);
  text-align: left;
  transition: border-color 130ms ease, background 130ms ease, transform 130ms ease;
}

.item-card:active {
  transform: scale(0.97);
}

.item-card.is-selected {
  border-color: rgba(255, 95, 143, 0.7);
  background:
    linear-gradient(145deg, rgba(255, 95, 143, 0.18), rgba(255, 95, 143, 0.03)),
    rgba(255, 255, 255, 0.03);
  box-shadow: 0 0 0 1px rgba(255, 95, 143, 0.18), 0 6px 18px rgba(255, 95, 143, 0.09);
}

.item-card.is-selected::after {
  content: "✓";
  position: absolute;
  top: 3px;
  right: 4px;
  display: grid;
  place-items: center;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  color: #1a0710;
  background: var(--pink-soft);
  font-size: 8px;
  font-weight: 800;
}

.item-icon {
  height: 44px;
  margin-bottom: 3px;
}

.item-icon svg {
  width: 100%;
  height: 100%;
}

.item-name {
  display: -webkit-box;
  min-height: 20px;
  overflow: hidden;
  color: var(--ink-soft);
  font-size: 8.2px;
  font-weight: 700;
  letter-spacing: 0.005em;
  line-height: 1.24;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.item-sub {
  margin-top: auto;
  padding-top: 3px;
  color: var(--faint);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.item-bars {
  display: flex;
  gap: 2px;
  margin-top: 3px;
}

.item-bars i {
  flex: 1;
  height: 2px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.item-bars i::after {
  content: "";
  display: block;
  width: var(--v, 50%);
  height: 100%;
  border-radius: inherit;
  background: var(--c, var(--green));
}

.wardrobe-footer {
  flex: 0 0 auto;
  padding: 8px 14px calc(9px + var(--safe-bottom));
  border-top: 1px solid var(--line-soft);
  background: linear-gradient(to top, rgba(5, 8, 15, 0.98), rgba(8, 12, 22, 0.92));
  backdrop-filter: blur(16px);
}

.prep-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 7px;
}

.prep-line__label {
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.prep-tokens {
  display: inline-flex;
  align-items: center;
  gap: 5px;
}

.prep-tokens i {
  display: block;
  width: 16px;
  height: 4px;
  border-radius: 99px;
  background: var(--pink);
  box-shadow: 0 0 8px rgba(255, 95, 143, 0.4);
}

.prep-tokens i.is-spent {
  background: rgba(255, 255, 255, 0.1);
  box-shadow: none;
}

.wardrobe-footer .btn {
  min-height: 50px;
}

/* ---------------- STORY ---------------- */
.screen--story {
  background:
    radial-gradient(95% 60% at 50% 0%, rgba(41, 55, 91, 0.25), transparent 58%),
    #060810;
}

.storybar {
  padding-bottom: 6px;
}

.pill-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 31px;
  padding: 0 10px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--ink-soft);
  background: rgba(255, 255, 255, 0.035);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.pill-btn svg {
  width: 14px;
  height: 14px;
}

.pill-btn:active {
  background: rgba(255, 255, 255, 0.09);
}

.storybar__mid {
  display: flex;
  align-items: baseline;
  gap: 7px;
}

.storybar__day {
  color: var(--pink-soft);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.storybar__clock {
  color: var(--ink);
  font-family: var(--serif);
  font-size: 16px;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.02em;
}

.shift-progress {
  flex: 0 0 3px;
  margin: 0 14px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.06);
}

.shift-progress span {
  display: block;
  width: 0%;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(to right, var(--cyan), var(--pink));
  transition: width 500ms ease;
}

.story-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  scrollbar-width: none;
  overscroll-behavior: contain;
}

.scene-art {
  position: relative;
  height: clamp(116px, 20.5vh, 176px);
  overflow: hidden;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  background: #0a1120;
}

.scene-art svg {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.scene-art::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 2;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(5, 7, 13, 0.05), transparent 50%, rgba(6, 8, 16, 0.72));
}

.scene-art.is-rain::after {
  content: "";
  position: absolute;
  inset: -20% -10%;
  z-index: 1;
  opacity: 0.55;
  pointer-events: none;
  background-image: repeating-linear-gradient(104deg, transparent 0 13px, rgba(180, 216, 255, 0.2) 13px 14px, transparent 14px 28px);
  background-size: 100px 120px;
  animation: rainSlide 460ms linear infinite;
}

.scene-art.is-snow::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  opacity: 0.55;
  pointer-events: none;
  background-image:
    radial-gradient(circle at 12% 20%, #fff 0 1px, transparent 1.5px),
    radial-gradient(circle at 42% 64%, #fff 0 1.2px, transparent 1.8px),
    radial-gradient(circle at 76% 33%, #fff 0 1px, transparent 1.5px),
    radial-gradient(circle at 88% 84%, #fff 0 1.2px, transparent 1.8px);
  background-size: 110px 110px, 150px 150px, 90px 90px, 180px 180px;
  animation: snowDrift 8s linear infinite;
}

.scene-art.is-fog::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(60% 40% at 30% 62%, rgba(180, 202, 230, 0.15), transparent 70%),
    radial-gradient(50% 34% at 78% 48%, rgba(180, 202, 230, 0.11), transparent 70%);
  animation: fogDrift 12s ease-in-out infinite alternate;
}

@keyframes rainSlide {
  from { transform: translate3d(0, -12%, 0); }
  to { transform: translate3d(-2%, 12%, 0); }
}

@keyframes snowDrift {
  from { transform: translate3d(0, -8%, 0); }
  to { transform: translate3d(2%, 8%, 0); }
}

@keyframes fogDrift {
  from { transform: translate3d(-3%, 0, 0) scale(1); }
  to { transform: translate3d(3%, -2%, 0) scale(1.06); }
}

.scene-body {
  position: relative;
  padding: 12px 18px 16px;
}

.outcome {
  margin: 0 0 12px;
  padding: 9px 11px 10px;
  border: 1px solid rgba(255, 95, 143, 0.18);
  border-left: 2px solid var(--pink);
  border-radius: 8px 12px 12px 8px;
  background: linear-gradient(100deg, rgba(255, 95, 143, 0.085), rgba(255, 255, 255, 0.015));
  animation: fadeUp 380ms ease both;
}

.outcome__eyebrow {
  display: block;
  margin-bottom: 4px;
  color: var(--pink-soft);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.outcome p {
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: 11.5px;
  font-style: italic;
  line-height: 1.5;
}

.deltas {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-top: 6px;
}

.delta-chip {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 2px 5px;
  border: 1px solid var(--line-soft);
  border-radius: 5px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.025);
  font-size: 6.8px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.delta-chip--good {
  color: var(--green);
  border-color: rgba(126, 224, 184, 0.2);
}

.delta-chip--bad {
  color: var(--danger);
  border-color: rgba(255, 116, 116, 0.18);
}

.delta-chip--chain {
  color: var(--cyan);
  border-color: rgba(110, 231, 242, 0.22);
}

.scene-meta {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 5px;
  color: var(--pink-soft);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.scene-place {
  overflow: hidden;
  max-width: 75%;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.scene-chain {
  padding: 2px 5px;
  border: 1px solid rgba(110, 231, 242, 0.26);
  border-radius: 4px;
  color: var(--cyan);
  background: rgba(110, 231, 242, 0.07);
  font-size: 6.5px;
  letter-spacing: 0.08em;
  animation: chainPulse 2.4s ease-in-out infinite;
}

@keyframes chainPulse {
  0%, 100% { opacity: 0.7; }
  50% { opacity: 1; }
}

.scene-body h2 {
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(21px, 5.9vw, 27px);
  font-weight: 500;
  letter-spacing: -0.025em;
  line-height: 1.12;
}

.scene-text {
  margin-top: 8px;
  color: var(--ink-soft);
  font-family: var(--serif);
  font-size: clamp(13.5px, 3.75vw, 15.2px);
  line-height: 1.63;
}

.scene-text p + p {
  margin-top: 8px;
}

.scene-text p:first-child::first-letter {
  padding-right: 1px;
  color: var(--pink-soft);
  font-size: 1.55em;
  font-weight: 500;
  line-height: 0.9;
}

.footline {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 11px;
  padding-top: 8px;
  border-top: 1px solid var(--line-soft);
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.4;
}

.footline b {
  color: var(--muted);
  font-weight: 800;
}

.footline .dot {
  width: 3px;
  height: 3px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--faint);
}

.choices {
  display: grid;
  gap: 6px;
  flex: 0 0 auto;
  padding: 8px 13px 5px;
  background: linear-gradient(to top, rgba(5, 8, 15, 0.99) 60%, rgba(6, 8, 15, 0.78));
}

.choice {
  position: relative;
  display: grid;
  grid-template-columns: 25px minmax(0, 1fr) 16px;
  align-items: center;
  gap: 8px;
  min-height: 49px;
  padding: 6px 9px;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.085);
  border-radius: 11px;
  background:
    linear-gradient(100deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.008)),
    rgba(9, 13, 23, 0.9);
  text-align: left;
  transition: border-color 130ms ease, background 130ms ease, transform 130ms ease;
}

.choice::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 2px;
  background: linear-gradient(to bottom, transparent, rgba(255, 95, 143, 0.65), transparent);
  opacity: 0;
  transition: opacity 140ms ease;
}

.choice:hover {
  border-color: rgba(255, 255, 255, 0.15);
}

.choice:active {
  transform: scale(0.988);
  background:
    linear-gradient(100deg, rgba(255, 95, 143, 0.12), rgba(255, 255, 255, 0.02)),
    rgba(9, 13, 23, 0.95);
}

.choice:active::before {
  opacity: 1;
}

.choice:disabled {
  opacity: 0.5;
}

.choice__num {
  display: grid;
  place-items: center;
  width: 25px;
  height: 25px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 7px;
  color: var(--pink-soft);
  background: rgba(255, 95, 143, 0.07);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.choice__body {
  min-width: 0;
}

.choice__label {
  display: block;
  color: var(--ink);
  font-size: clamp(11.5px, 3.2vw, 13.4px);
  font-weight: 700;
  letter-spacing: -0.005em;
  line-height: 1.25;
}

.choice__tags {
  display: flex;
  flex-wrap: wrap;
  gap: 3px;
  margin-top: 3px;
}

.choice__tags:empty {
  display: none;
}

.choice-tag {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  color: var(--faint);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.choice-tag i {
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: currentColor;
}

.choice-tag--good {
  color: var(--green);
}

.choice-tag--bad {
  color: var(--danger);
}

.choice-tag--chain {
  color: var(--cyan);
}

.choice__chev {
  color: rgba(255, 255, 255, 0.26);
  font-size: 14px;
  text-align: right;
}

.choice.is-picked {
  border-color: rgba(255, 95, 143, 0.55);
  background: rgba(255, 95, 143, 0.12);
}

.story-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  flex: 0 0 auto;
  padding: 3px 15px calc(7px + var(--safe-bottom));
  color: rgba(255, 255, 255, 0.22);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.14em;
}

/* ---------------- REPORT ---------------- */
.screen--report {
  background:
    radial-gradient(100% 65% at 50% 0%, rgba(255, 191, 146, 0.14), transparent 60%),
    linear-gradient(to bottom, #111324, #070a12 58%);
}

.report-art {
  position: relative;
  flex: 0 0 22%;
  min-height: 118px;
  overflow: hidden;
  border-bottom: 1px solid rgba(255, 255, 255, 0.07);
}

.report-art svg {
  width: 100%;
  height: 100%;
}

.report-art::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 45%, #0a0d17 100%);
}

.report-scroll {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 17px 20px calc(18px + var(--safe-bottom));
  scrollbar-width: none;
}

.report-head h1 {
  margin-top: 8px;
  color: var(--ink);
  font-family: var(--serif);
  font-size: clamp(31px, 8.6vw, 42px);
  font-weight: 500;
  letter-spacing: -0.04em;
  line-height: 0.98;
}

.report-head > p {
  margin-top: 10px;
  color: var(--muted);
  font-family: var(--serif);
  font-size: 12.5px;
  line-height: 1.6;
}

.report-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 16px;
}

.report-stat {
  padding: 10px 11px;
  border: 1px solid var(--line-soft);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.028);
}

.report-stat span {
  display: block;
  color: var(--faint);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.report-stat strong {
  display: block;
  margin-top: 2px;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 22px;
  font-weight: 500;
  line-height: 1.1;
}

.report-stat em {
  color: var(--muted);
  font-family: var(--sans);
  font-size: 8px;
  font-style: normal;
  font-weight: 700;
}

.report-note {
  margin-top: 10px;
  padding: 11px 12px;
  border-left: 2px solid var(--gold);
  border-radius: 0 10px 10px 0;
  color: var(--ink-soft);
  background: rgba(255, 210, 125, 0.06);
  font-family: var(--serif);
  font-size: 12px;
  font-style: italic;
  line-height: 1.55;
}

.report-shoe {
  margin-top: 12px;
  padding: 11px 12px;
  border: 1px solid var(--line-soft);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.022);
}

.report-shoe__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.report-shoe__head strong {
  color: var(--ink-soft);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.report-shoe__head span {
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 700;
}

.report-shoe .cond-grid {
  grid-template-columns: repeat(4, 1fr);
}

.report-shoe .condition-warning {
  margin-top: 7px;
  color: var(--gold);
  font-size: 8px;
  line-height: 1.4;
}

.report-scroll .btn {
  margin-top: 14px;
}

/* ---------------- SHEETS ---------------- */
.sheet-scrim {
  position: absolute;
  inset: 0;
  z-index: 40;
  background: rgba(2, 4, 8, 0.72);
  opacity: 0;
  pointer-events: none;
  transition: opacity 240ms ease;
  backdrop-filter: blur(3px);
}

.sheet-scrim.is-open {
  opacity: 1;
  pointer-events: auto;
}

.sheet {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  max-height: 86%;
  padding-bottom: var(--safe-bottom);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-bottom: 0;
  border-radius: 24px 24px 0 0;
  background:
    radial-gradient(80% 40% at 20% 0%, rgba(255, 95, 143, 0.09), transparent 60%),
    linear-gradient(to bottom, #111728, #080b14);
  box-shadow: 0 -20px 70px rgba(0, 0, 0, 0.55);
  transform: translateY(104%);
  transition: transform 340ms cubic-bezier(0.22, 0.9, 0.2, 1);
  visibility: hidden;
}

.sheet.is-open {
  transform: translateY(0);
  visibility: visible;
}

.sheet__handle {
  width: 34px;
  height: 3px;
  margin: 8px auto 5px;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.17);
}

.sheet__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 16px 10px;
}

.sheet__head h2 {
  margin-top: 3px;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 25px;
  font-weight: 500;
  letter-spacing: -0.025em;
}

.sheet__head .icon-btn {
  width: 31px;
  height: 31px;
  margin-top: 3px;
}

.sheet__scroll {
  min-height: 0;
  overflow-y: auto;
  padding: 0 16px calc(22px + var(--safe-bottom));
  scrollbar-width: none;
}

.status-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
  padding: 9px 11px;
  border: 1px solid var(--line-soft);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.025);
}

.status-top div {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.status-top strong {
  color: var(--ink);
  font-family: var(--serif);
  font-size: 15px;
  font-weight: 500;
}

.status-top span {
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.status-top .status-weather {
  padding: 4px 7px;
  border: 1px solid var(--line-soft);
  border-radius: 99px;
  color: var(--cyan-soft);
  background: rgba(110, 231, 242, 0.06);
  font-size: 7px;
  letter-spacing: 0.08em;
}

.meters {
  display: grid;
  gap: 8px;
}

.meter {
  display: grid;
  grid-template-columns: 88px 1fr 30px;
  align-items: center;
  gap: 8px;
}

.meter__label {
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
}

.meter__track {
  height: 5px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.07);
}

.meter__fill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(to right, var(--cyan), var(--green));
  transition: width 300ms ease;
}

.meter__fill.is-mid {
  background: linear-gradient(to right, var(--gold), #ffa96d);
}

.meter__fill.is-bad {
  background: linear-gradient(to right, var(--danger), #ff9a5f);
}

.meter__value {
  color: var(--ink-soft);
  font-size: 9px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.meter--danger .meter__fill {
  background: linear-gradient(to right, #b76e79, var(--danger));
}

.status-section-title {
  margin: 16px 0 7px;
  color: var(--faint);
  font-size: 7.5px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.status-shoe {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border: 1px solid var(--line-soft);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.022);
}

.status-shoe__icon {
  width: 50px;
  height: 43px;
  flex: 0 0 auto;
}

.status-shoe__icon svg {
  width: 100%;
  height: 100%;
}

.status-shoe__body {
  min-width: 0;
}

.status-shoe__body strong {
  display: block;
  overflow: hidden;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 13px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.status-shoe__body span {
  display: block;
  color: var(--faint);
  font-size: 8px;
  font-weight: 700;
  line-height: 1.45;
}

.status-shoe__body span b {
  color: var(--ink-soft);
  font-weight: 800;
}

.status-counters {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
}

.status-counter {
  padding: 8px 6px;
  border: 1px solid var(--line-soft);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.022);
  text-align: center;
}

.status-counter strong {
  display: block;
  color: var(--ink);
  font-family: var(--serif);
  font-size: 19px;
  font-weight: 500;
  line-height: 1;
}

.status-counter span {
  display: block;
  margin-top: 3px;
  color: var(--faint);
  font-size: 6.5px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.status-log {
  display: grid;
  gap: 5px;
}

.status-log__row {
  display: grid;
  grid-template-columns: 34px 1fr;
  gap: 7px;
  padding: 6px 0;
  border-bottom: 1px solid var(--line-soft);
}

.status-log__row:last-child {
  border-bottom: 0;
}

.status-log__time {
  color: var(--pink-soft);
  font-size: 7px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.status-log__text {
  color: var(--muted);
  font-size: 9px;
  line-height: 1.4;
}

.status-log__text b {
  color: var(--ink-soft);
  font-weight: 700;
}

.status-empty {
  padding: 10px 0;
  color: var(--faint);
  font-size: 9px;
  font-style: italic;
}

.status-note {
  margin-top: 10px;
  padding: 9px 10px;
  border: 1px dashed rgba(255, 255, 255, 0.1);
  border-radius: 9px;
  color: var(--faint);
  font-size: 8px;
  line-height: 1.5;
}

.status-note b {
  color: var(--pink-soft);
}

/* help */
.help-row {
  display: grid;
  grid-template-columns: 27px 1fr;
  gap: 10px;
  padding: 11px 0;
  border-bottom: 1px solid var(--line-soft);
}

.help-row:last-of-type {
  border-bottom: 0;
}

.help-num {
  display: grid;
  place-items: center;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(255, 95, 143, 0.3);
  border-radius: 50%;
  color: var(--pink-soft);
  background: rgba(255, 95, 143, 0.07);
  font-size: 9px;
  font-weight: 800;
}

.help-row strong {
  display: block;
  color: var(--ink);
  font-size: 11px;
  font-weight: 700;
}

.help-row p {
  margin-top: 3px;
  color: var(--muted);
  font-size: 9.5px;
  line-height: 1.55;
}

.help-note {
  margin: 12px 0;
  padding: 10px 11px;
  border-left: 2px solid var(--cyan);
  border-radius: 0 9px 9px 0;
  color: var(--ink-soft);
  background: rgba(110, 231, 242, 0.06);
  font-family: var(--serif);
  font-size: 10.5px;
  line-height: 1.55;
}

/* ---------------- Tears / toast ---------------- */
.tears {
  position: absolute;
  inset: 0;
  z-index: 35;
  overflow: hidden;
  pointer-events: none;
  opacity: 0;
  transition: opacity 400ms ease;
}

.tears.is-active {
  opacity: 1;
}

.tears span {
  position: absolute;
  top: -8%;
  width: 2px;
  height: 28px;
  border-radius: 99px;
  background: linear-gradient(to bottom, transparent, rgba(170, 226, 255, 0.65), rgba(170, 226, 255, 0.05));
  filter: blur(0.3px);
  animation: tearFall 2.6s linear infinite;
}

.tears span:nth-child(1) { left: 13%; animation-delay: 0.1s; }
.tears span:nth-child(2) { left: 31%; height: 20px; animation-delay: 0.9s; }
.tears span:nth-child(3) { left: 49%; height: 34px; animation-delay: 0.4s; }
.tears span:nth-child(4) { left: 68%; height: 24px; animation-delay: 1.4s; }
.tears span:nth-child(5) { left: 86%; height: 30px; animation-delay: 0.7s; }

@keyframes tearFall {
  0% { transform: translateY(-10vh); opacity: 0; }
  15% { opacity: 0.85; }
  80% { opacity: 0.55; }
  100% { transform: translateY(105vh); opacity: 0; }
}

.toast {
  position: absolute;
  left: 50%;
  bottom: calc(86px + var(--safe-bottom));
  z-index: 80;
  max-width: 86%;
  padding: 8px 13px;
  border: 1px solid rgba(255, 255, 255, 0.13);
  border-radius: 999px;
  color: var(--ink);
  background: rgba(12, 17, 30, 0.94);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1.4;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, 8px);
  transition: opacity 200ms ease, transform 240ms ease;
  backdrop-filter: blur(12px);
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

@keyframes fadeUp {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: translateY(0); }
}

/* ---------------- small screens ---------------- */
@media (max-width: 370px) {
  .item-grid {
    gap: 5px;
  }

  .item-card {
    min-height: 86px;
  }

  .item-name {
    font-size: 7.6px;
  }

  .outfit-preview {
    flex-basis: 92px;
  }

  .outfit-meta h2 {
    font-size: 18px;
  }

  .meter {
    grid-template-columns: 76px 1fr 26px;
  }

  .choice {
    min-height: 46px;
    padding: 5px 8px;
  }

  .choice__label {
    font-size: 11px;
  }
}

@media (max-height: 740px) and (max-width: 640px) {
  .scene-art {
    height: 108px;
  }

  .scene-body {
    padding-top: 10px;
  }

  .scene-text {
    font-size: 13px;
    line-height: 1.55;
  }

  .choices {
    gap: 5px;
    padding-top: 6px;
  }

  .choice {
    min-height: 44px;
  }

  .choice__label {
    font-size: 11.3px;
  }

  .choice__tags {
    margin-top: 2px;
  }

  .outfit-card {
    min-height: 134px;
  }

  .outfit-preview {
    min-height: 110px;
  }
}

