      detail = `<path d="M15 11 H27" stroke="${sock.color2}" stroke-width="2" stroke-dasharray="1 1.6" opacity=".85"/>`;
    } else if (pattern === "shine") {
      detail = `<path d="M17 13 Q18 26 23 35" stroke="#fff" stroke-width="1" opacity=".28"/>`;
    }
    return `<svg viewBox="0 0 44 44" aria-hidden="true"><defs><linearGradient id="${uid}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${sock.color2}"/><stop offset="1" stop-color="${sock.color}"/></linearGradient></defs><path d="${sockPath()}" fill="url(#${uid})" opacity="${sock.pattern === "sheer" ? ".82" : "1"}"/><path d="${sockPath()}" fill="none" stroke="#000" stroke-opacity=".25" stroke-width=".7"/>${detail}<path d="M15 9 H27" stroke="#fff" stroke-opacity=".25" stroke-width=".8"/></svg>`;
  }

