 const pct = clamp(value);
 const cls = invert ? (value>60?'is-bad':value>35?'is-mid':'') : (value>60?'':value>35?'is-mid':'is-bad');
 return `<div class="cond-bar"><i class="${cls}" style="width:${pct}%"></i></div>`;
}
