  function freshState() {
    return {
      v: 1,
      day: 1,
      phase: "wardrobe",
      nodeId: "gece-baslangic",
      elapsed: 0,
      scenes: 0,
      stats: { sinir: 32, konfor: 58, temizlik: 88, nem: 8, kum: 3, koku: 7, enerji: 74, itibar: 48 },

